<script lang="ts">
 import {authClient} from '$lib/auth-client';import {onMount} from 'svelte';let {model,t,email}:{email:string;model:Record<string,Record<string,any>[]>;t:(s:string)=>string}=$props();let enabled=$state(false),mail=$state(false),message=$state('');let overdue=$derived(model.tasks.filter(task=>task.status!=='done'&&task.due_at&&Date.parse(task.due_at)<Date.now()));let alerts=$derived(model.lab_alerts.filter(a=>a.status!=='within_range'));let shortage=$derived(model.materials.filter(m=>Number(m.available)<Number(m.reorder_at)));
 onMount(async()=>{try{const res=await fetch('/api/notifications');if(res.ok){const data=await res.json();enabled=data.email_digest;mail=data.mail_connected;}}catch{message=t('CONNECTION_FAILED');}});
 async function save(){try{const res=await fetch('/api/notifications',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({email_digest:enabled})});message=res.ok?t('saved'):t((await res.json()).message);}catch{message=t('CONNECTION_FAILED');}}
</script>
<section class="card"><h2>{t('notifications')}</h2>{#if !overdue.length&&!alerts.length&&!shortage.length}<p>{t('noAlerts')}</p>{/if}{#each overdue as task}<p><a href="/app/today">{task.title}</a> · {t('overdue')} · {task.due_at}</p>{/each}{#each alerts as a}<p><a href="/app/lab">{a.lot_code} · {a.name}</a> · {t(a.status)}</p>{/each}{#each shortage as m}<p><a href="/app/bottling">{m.code} · {m.name}</a> · {m.available} / {m.reorder_at} {m.unit}</p>{/each}<label class="check"><input type="checkbox" bind:checked={enabled} />{t('emailDigest')}</label>{#if !mail}<p class="muted">{t('MAIL_NOT_CONFIGURED')}</p>{/if}<p class="muted">{t('verifiedEmailDigest')}</p>{#if mail}<button onclick={async()=>{try{const r=await authClient.sendVerificationEmail({email,callbackURL:location.origin+'/app/today'});message=r.error?t('AUTH_REQUEST_FAILED'):t('resetEmailSent');}catch{message=t('CONNECTION_FAILED');}}}>{t('verifyEmail')}</button>{/if}<button onclick={save}>{t('save')}</button><p role="status">{message}</p></section>
<style>.check{display:flex;align-items:center;gap:10px;margin:20px 0}.check input{width:18px;height:18px}</style>
